function speedCalc(opts){
  opts=opts||{};
  var hasD = opts.distance!=null && String(opts.distance).trim()!=='';
  var hasT = opts.time!=null && String(opts.time).trim()!=='';
  var hasV = opts.speed!=null && String(opts.speed).trim()!=='';
  var cnt=(hasD?1:0)+(hasT?1:0)+(hasV?1:0);
  if(cnt!==2) return {ok:false, reason:'请填写距离/时间/速度中的任意两项'};
  var d=hasD?Number(opts.distance):0, t=hasT?Number(opts.time):0, v=hasV?Number(opts.speed):0;
  if(hasD && !(isFinite(d) && d>=0)) return {ok:false, reason:'距离无效'};
  if(hasT && !(isFinite(t) && t>0)) return {ok:false, reason:'时间无效（需 > 0）'};
  if(hasV && !(isFinite(v) && v>=0)) return {ok:false, reason:'速度无效'};
  if(!hasV) return {ok:true, distance:d, time:t, speed:d/t, solved:'speed'};
  if(!hasD) return {ok:true, distance:v*t, time:t, speed:v, solved:'distance'};
  if(!(v>0)) return {ok:false, reason:'速度需 > 0 才能求时间'};
  return {ok:true, distance:d, time:d/v, speed:v, solved:'time'};
}

var EXPORTS={speedCalc:speedCalc};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpeedForgePure = EXPORTS; }
